function createTransitionRunner(executor) {
  if (typeof executor !== 'function') throw new TypeError('executor must be a function');
  let busy = false;

  async function run(sequence) {
    if (!Array.isArray(sequence)) throw new TypeError('sequence must be an array');
    if (busy) return { accepted: false, results: [] };
    busy = true;
    const snapshot = sequence.slice();
    const results = [];
    for (let index = 0; index < snapshot.length; index += 1) {
      results.push(await executor(snapshot[index], index));
    }
    busy = false;
    return { accepted: true, results };
  }

  function isBusy() {
    return busy;
  }

  return { run, isBusy };
}

module.exports = { createTransitionRunner };
```

