'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createTransitionRunner']);
const { createTransitionRunner } = api;

(async () => {
  assert.throws(() => createTransitionRunner(null), TypeError);
  assert.throws(() => createTransitionRunner({}), TypeError);

  const order = [];
  let releaseFirst;
  const gate = new Promise(resolve => { releaseFirst = resolve; });
  const runner = createTransitionRunner(async (item, index) => {
    order.push(`start:${item}:${index}`);
    if (index === 0) await gate;
    order.push(`end:${item}:${index}`);
    return item * 2;
  });
  assert.strictEqual(runner.isBusy(), false);
  const sequence = [2, 3];
  const active = runner.run(sequence);
  assert.strictEqual(runner.isBusy(), true);
  sequence[1] = 99;
  sequence.push(100);
  const rejected = await runner.run([8]);
  assert.deepStrictEqual(rejected, { accepted: false, results: [] });
  assert.strictEqual(runner.isBusy(), true);
  releaseFirst();
  assert.deepStrictEqual(await active, { accepted: true, results: [4, 6] });
  assert.deepStrictEqual(order, ['start:2:0', 'end:2:0', 'start:3:1', 'end:3:1']);
  assert.strictEqual(runner.isBusy(), false);

  assert.deepStrictEqual(await runner.run([]), { accepted: true, results: [] });
  assert.strictEqual(runner.isBusy(), false);
  await assert.rejects(runner.run(null), TypeError);
  assert.strictEqual(runner.isBusy(), false);

  const sentinel = new Error('executor failed');
  let attempts = 0;
  const failing = createTransitionRunner(async item => {
    attempts += 1;
    if (item === 'fail') throw sentinel;
    return item;
  });
  await assert.rejects(failing.run(['ok', 'fail', 'never']), error => error === sentinel);
  assert.strictEqual(attempts, 2);
  assert.strictEqual(failing.isBusy(), false);
  assert.deepStrictEqual(await failing.run(['later']), { accepted: true, results: ['later'] });
  assert.strictEqual(failing.isBusy(), false);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

